<fieldset class="m3-card m3-card--outlined" data-pathway-row="subject" style="min-width:0;padding:16px;margin-block:12px"><legend>{{ __('Subject rule') }}</legend>
<x-page.field :id="'pathway-subject-'.$index.'-id'" :name="'score_subjects['.$index.'][subject_id]'" type="select" :label="__('School subject')" :value="$row['subject_id']" :options="$subjects" :placeholder="__('Choose a subject')" :required="true" :restore-old-input="false" />
<x-page.field :id="'pathway-subject-'.$index.'-minimum'" :name="'score_subjects['.$index.'][minimum_percent]'" type="number" :label="__('Minimum required percentage, if any')" :value="$row['minimum_bp'] === null ? '' : \App\Services\Academics\AcademicNumbers::decimal($row['minimum_bp'])" min="0" max="100" step="0.01" :restore-old-input="false" />
<input type="hidden" name="score_subjects[{{ $index }}][counts_for_score]" value="0"><label for="pathway-subject-{{ $index }}-counts"><input id="pathway-subject-{{ $index }}-counts" type="checkbox" name="score_subjects[{{ $index }}][counts_for_score]" value="1" @checked($row['counts_for_score'])> {{ __('Count this subject toward the score') }}</label>
<button type="button" class="m3-button m3-button--text" data-pathway-remove>{{ __('Remove subject rule') }}</button></fieldset>
